True def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    for c in range(w):
        if out[h - 1][c] != 5:
            continue
        points = [r for r in range(h) if out[r][c] != 0]
        if not points:
            continue
        for r in range(points[0]):
            out[r][c] = out[points[0]][c]
        for a, b in zip(points, points[1:]):
            color = out[b][c]
            for r in range(a + 1, b):
                out[r][c] = color
        for r in range(points[-1] + 1, h):
            out[r][c] = out[points[-1]][c]
    return out
